CustomField.formula:
/* 
This formula will traverse the Account hierarchy from (including) current record all the way to the top (up to 6 levels) and 
will display the value of the "Primary CDE" field of the Parent Account */ 

IF(ISBLANK( ParentId ), Primary_CDE__c , 

IF(ISBLANK( Parent.ParentId), Parent.Primary_CDE__c , 

IF(ISBLANK( Parent.Parent.ParentId), Parent.Parent.Primary_CDE__c , 

IF(ISBLANK( Parent.Parent.Parent.ParentId), 
Parent.Parent.Parent.Primary_CDE__c , 

IF(ISBLANK( Parent.Parent.Parent.Parent.ParentId ), 
Parent.Parent.Parent.Parent.Primary_CDE__c , 

IF(ISBLANK( Parent.Parent.Parent.Parent.Parent.ParentId), 
Parent.Parent.Parent.Parent.Parent.Primary_CDE__c , 

"") 
) 
) 
) 
) 
)
